"""Read-only structural audit of a UTF-8 comma or tab delimited table."""

from __future__ import annotations

import argparse
import csv
import hashlib
import io
import json
import os

from confined_input import ConfinedInputError, open_approved_file

DEFAULT_MAX_BYTES = 20_000_000
MAX_EXAMPLES = 20
HEADER_MODES = {"present", "absent"}


class AuditInputError(ValueError):
    """The requested source cannot be safely audited under this contract."""


def audit(
    approved_root: str,
    input_relative: str,
    delimiter: str = ",",
    max_bytes: int = DEFAULT_MAX_BYTES,
    header_mode: str = "absent",
) -> dict:
    if len(delimiter) != 1 or delimiter in {"\n", "\r", '"'}:
        raise AuditInputError("delimiter_must_be_one_non_quote_character")
    if not 1 <= max_bytes <= DEFAULT_MAX_BYTES:
        raise AuditInputError("max_bytes_outside_supported_range")
    if header_mode not in HEADER_MODES:
        raise AuditInputError("header_mode_must_be_present_or_absent")
    with open_approved_file(approved_root, input_relative) as handle:
        before = os.fstat(handle.fileno())
        body = handle.read(max_bytes + 1)
        after = os.fstat(handle.fileno())
    if (
        before.st_dev,
        before.st_ino,
        before.st_size,
        before.st_mtime_ns,
        before.st_ctime_ns,
    ) != (
        after.st_dev,
        after.st_ino,
        after.st_size,
        after.st_mtime_ns,
        after.st_ctime_ns,
    ):
        raise AuditInputError("input_changed_during_read")
    if len(body) > max_bytes:
        raise AuditInputError("input_exceeds_max_bytes")

    examples: list[dict] = []
    issue_count = 0

    def issue(kind: str, record: int, physical_line: int) -> None:
        nonlocal issue_count
        issue_count += 1
        if len(examples) < MAX_EXAMPLES:
            examples.append(
                {"kind": kind, "record": record, "physical_line": physical_line}
            )

    header: list[str] = []
    data_rows = 0
    column_count: int | None = None
    prior_limit = csv.field_size_limit()
    csv.field_size_limit(max_bytes)
    try:
        with io.StringIO(body.decode("utf-8-sig"), newline="") as handle:
            reader = csv.reader(handle, delimiter=delimiter, strict=True)
            try:
                for record, row in enumerate(reader, start=1):
                    if record == 1:
                        column_count = len(row)
                        if header_mode == "present":
                            header = row
                            if not header:
                                issue("empty_header", record, reader.line_num)
                            normalized = [name.strip().casefold() for name in header]
                            if any(not name for name in normalized):
                                issue("blank_header_name", record, reader.line_num)
                            if len(set(normalized)) != len(normalized):
                                issue("duplicate_header_name", record, reader.line_num)
                        else:
                            data_rows += 1
                    else:
                        data_rows += 1
                        if len(row) != column_count:
                            issue("row_width_mismatch", record, reader.line_num)
                    if any("\x00" in field for field in row):
                        issue("nul_character", record, reader.line_num)
            except csv.Error:
                issue("malformed_csv", data_rows + 2, reader.line_num)
    finally:
        csv.field_size_limit(prior_limit)
    if column_count is None and issue_count == 0:
        issue("missing_header" if header_mode == "present" else "empty_input", 0, 0)
    return {
        "record_type": "csv_structure_audit/v1",
        "status": "pass" if issue_count == 0 else "fail",
        "input_sha256": hashlib.sha256(body).hexdigest(),
        "header_mode": header_mode,
        "header": header,
        "column_count": column_count or 0,
        "data_rows": data_rows,
        "issue_count": issue_count,
        "issue_examples": examples,
        "examples_truncated": issue_count > len(examples),
    }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--approved-root", required=True)
    parser.add_argument("--input-relative", required=True)
    parser.add_argument("--header-mode", choices=sorted(HEADER_MODES), default="absent")
    parser.add_argument("--delimiter", default=",")
    parser.add_argument("--max-bytes", type=int, default=DEFAULT_MAX_BYTES)
    args = parser.parse_args(argv)
    try:
        report = audit(
            args.approved_root,
            args.input_relative,
            args.delimiter,
            args.max_bytes,
            args.header_mode,
        )
    except (AuditInputError, ConfinedInputError, OSError, UnicodeError) as error:
        report = {
            "record_type": "csv_structure_audit/v1",
            "status": "refused",
            "reason": str(error)
            if isinstance(error, (AuditInputError, ConfinedInputError))
            else "input_unreadable",
        }
    print(json.dumps(report, ensure_ascii=False, sort_keys=True))
    return {"pass": 0, "fail": 1, "refused": 2}[report["status"]]


if __name__ == "__main__":
    raise SystemExit(main())

"""Open selected task material below an explicit root without following symlinks."""

from __future__ import annotations

import os
import stat
from collections.abc import Iterator
from contextlib import contextmanager
from typing import BinaryIO


class ConfinedInputError(ValueError):
    """The requested input is outside the declared, no-follow read scope."""


def _flags(directory: bool) -> int:
    if (
        os.name != "posix"
        or not hasattr(os, "O_NOFOLLOW")
        or not hasattr(os, "O_DIRECTORY")
    ):
        raise ConfinedInputError("no_follow_file_operations_unavailable")
    flags = os.O_RDONLY | os.O_NOFOLLOW
    if directory:
        flags |= os.O_DIRECTORY
    else:
        if not hasattr(os, "O_NONBLOCK"):
            raise ConfinedInputError("nonblocking_file_open_unavailable")
        flags |= os.O_NONBLOCK
    return flags


def relative_parts(
    relative: str | os.PathLike[str], *, allow_root: bool = False
) -> tuple[str, ...]:
    try:
        raw = os.fspath(relative)
    except TypeError:
        raise ConfinedInputError("input_path_must_be_relative") from None
    if raw == "." and allow_root:
        return ()
    if not isinstance(raw, str) or not raw or raw.startswith("/"):
        raise ConfinedInputError("input_path_must_be_relative")
    parts = tuple(raw.split("/"))
    if any(part in {"", ".", ".."} or "\x00" in part for part in parts):
        raise ConfinedInputError("input_path_contains_traversal_or_empty_component")
    return parts


def _root_parts(approved_root: str | os.PathLike[str]) -> tuple[str, ...]:
    try:
        raw = os.fspath(approved_root)
    except TypeError:
        raise ConfinedInputError("approved_root_must_be_absolute") from None
    if not isinstance(raw, str) or not raw.startswith("/"):
        raise ConfinedInputError("approved_root_must_be_absolute")
    parts = tuple(raw.split("/")[1:])
    if not parts or any(part in {"", ".", ".."} or "\x00" in part for part in parts):
        raise ConfinedInputError(
            "approved_root_must_be_a_normalized_directory_below_slash"
        )
    return parts


@contextmanager
def open_approved_directory(approved_root: str, relative: str = ".") -> Iterator[int]:
    parts = _root_parts(approved_root)
    children = relative_parts(relative, allow_root=True)
    flags = _flags(directory=True)
    opened: list[int] = []
    try:
        opened.append(os.open("/", flags))
        for part in (*parts, *children):
            opened.append(os.open(part, flags, dir_fd=opened[-1]))
    except OSError:
        for descriptor in reversed(opened):
            os.close(descriptor)
        raise ConfinedInputError("directory_missing_or_symlinked") from None
    try:
        yield opened[-1]
    finally:
        for descriptor in reversed(opened):
            os.close(descriptor)


@contextmanager
def open_approved_file(approved_root: str, relative: str) -> Iterator[BinaryIO]:
    parts = relative_parts(relative)
    parent = "/".join(parts[:-1]) or "."
    with open_approved_directory(approved_root, parent) as directory:
        try:
            descriptor = os.open(parts[-1], _flags(directory=False), dir_fd=directory)
        except OSError:
            raise ConfinedInputError("file_missing_or_symlinked") from None
        try:
            if not stat.S_ISREG(os.fstat(descriptor).st_mode):
                raise ConfinedInputError("input_must_be_regular_file")
            with os.fdopen(descriptor, "rb") as handle:
                descriptor = -1
                yield handle
        finally:
            if descriptor != -1:
                os.close(descriptor)

"""Read-only audit of JSON Lines event identities and payload consistency."""

from __future__ import annotations

import argparse
import hashlib
import json
import os
from decimal import Decimal, InvalidOperation

from confined_input import ConfinedInputError, open_approved_file

DEFAULT_MAX_BYTES = 20_000_000
DEFAULT_MAX_RECORDS = 100_000
MAX_EXAMPLES = 20


class AuditInputError(ValueError):
    """The requested source cannot be safely audited under this contract."""


def _unique_pairs(pairs: list[tuple[str, object]]) -> dict:
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate_json_key")
        result[key] = value
    return result


def _reject_constant(value: str) -> None:
    raise ValueError("non_finite_json_number")


def _canonical(value: object) -> list:
    """Retain exact parsed numeric values and type boundaries in the digest."""
    if isinstance(value, dict):
        pairs = []
        for key in sorted(value):
            key.encode("utf-8")
            pairs.append([key, _canonical(value[key])])
        return ["object", pairs]
    if isinstance(value, list):
        return ["array", [_canonical(item) for item in value]]
    if isinstance(value, str):
        value.encode("utf-8")
        return ["string", value]
    if isinstance(value, bool):
        return ["boolean", value]
    if value is None:
        return ["null"]
    if isinstance(value, int):
        return ["integer", str(value)]
    if isinstance(value, Decimal):
        return ["decimal", str(value)]
    raise ValueError("unsupported_json_value")


def audit(
    approved_root: str,
    input_relative: str,
    id_field: str,
    max_bytes: int = DEFAULT_MAX_BYTES,
    max_records: int = DEFAULT_MAX_RECORDS,
) -> dict:
    if not id_field:
        raise AuditInputError("id_field_must_be_one_top_level_key")
    if (
        not 1 <= max_bytes <= DEFAULT_MAX_BYTES
        or not 1 <= max_records <= DEFAULT_MAX_RECORDS
    ):
        raise AuditInputError("resource_limits_outside_supported_range")
    with open_approved_file(approved_root, input_relative) as handle:
        before = os.fstat(handle.fileno())
        body = handle.read(max_bytes + 1)
        after = os.fstat(handle.fileno())
    if (
        before.st_dev,
        before.st_ino,
        before.st_size,
        before.st_mtime_ns,
        before.st_ctime_ns,
    ) != (
        after.st_dev,
        after.st_ino,
        after.st_size,
        after.st_mtime_ns,
        after.st_ctime_ns,
    ):
        raise AuditInputError("input_changed_during_read")
    if len(body) > max_bytes:
        raise AuditInputError("input_exceeds_max_bytes")
    decoded = body.decode("utf-8-sig")
    # Stop after the first record beyond the limit. An unrestricted split can
    # allocate millions of list entries even when the byte limit is bounded.
    lines = decoded.split("\n", max_records) if decoded else []
    if lines and lines[-1] == "":
        lines.pop()
    if len(lines) > max_records:
        raise AuditInputError("input_exceeds_max_records")

    examples: list[dict] = []
    counts = {
        "valid_events": 0,
        "identical_repeats": 0,
        "conflicting_repeats": 0,
        "invalid_records": 0,
    }
    seen: dict[str, tuple[str, int]] = {}

    def problem(kind: str, line: int, first_line: int | None = None) -> None:
        counts["invalid_records" if first_line is None else "conflicting_repeats"] += 1
        if len(examples) < MAX_EXAMPLES:
            example = {"kind": kind, "line": line}
            if first_line is not None:
                example["first_line"] = first_line
            examples.append(example)

    for line_number, raw_line in enumerate(lines, start=1):
        line = raw_line.removesuffix("\r")
        if not line.strip():
            problem("blank_line", line_number)
            continue
        try:
            event = json.loads(
                line,
                object_pairs_hook=_unique_pairs,
                parse_constant=_reject_constant,
                parse_float=Decimal,
            )
        except (json.JSONDecodeError, ValueError, InvalidOperation, RecursionError):
            problem("invalid_json_or_duplicate_key", line_number)
            continue
        if not isinstance(event, dict):
            problem("event_must_be_object", line_number)
            continue
        identity = event.get(id_field)
        if (
            isinstance(identity, bool)
            or not isinstance(identity, (str, int))
            or isinstance(identity, str)
            and not identity
        ):
            problem("missing_or_invalid_identity", line_number)
            continue
        try:
            key = json.dumps(
                _canonical(identity), ensure_ascii=False, separators=(",", ":")
            )
            canonical = json.dumps(
                _canonical(event), ensure_ascii=False, separators=(",", ":")
            )
        except (ValueError, UnicodeError, RecursionError):
            problem("invalid_json_value", line_number)
            continue
        digest = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
        counts["valid_events"] += 1
        if key in seen:
            prior_digest, first_line = seen[key]
            if digest == prior_digest:
                counts["identical_repeats"] += 1
            else:
                problem("conflicting_identity_payload", line_number, first_line)
        else:
            seen[key] = (digest, line_number)
    if not lines:
        problem("empty_input", 0)
    failure_count = counts["conflicting_repeats"] + counts["invalid_records"]
    return {
        "record_type": "jsonl_identity_audit/v1",
        "status": "pass" if failure_count == 0 else "fail",
        "input_sha256": hashlib.sha256(body).hexdigest(),
        "id_field": id_field,
        "line_count": len(lines),
        "distinct_identities": len(seen),
        "counts": counts,
        "issue_examples": examples,
        "examples_truncated": failure_count > len(examples),
    }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--approved-root", required=True)
    parser.add_argument("--input-relative", required=True)
    parser.add_argument("--id-field", required=True)
    parser.add_argument("--max-bytes", type=int, default=DEFAULT_MAX_BYTES)
    parser.add_argument("--max-records", type=int, default=DEFAULT_MAX_RECORDS)
    args = parser.parse_args(argv)
    try:
        report = audit(
            args.approved_root,
            args.input_relative,
            args.id_field,
            args.max_bytes,
            args.max_records,
        )
    except (AuditInputError, ConfinedInputError, OSError, UnicodeError) as error:
        report = {
            "record_type": "jsonl_identity_audit/v1",
            "status": "refused",
            "reason": str(error)
            if isinstance(error, (AuditInputError, ConfinedInputError))
            else "input_unreadable",
        }
    print(json.dumps(report, ensure_ascii=False, sort_keys=True))
    return {"pass": 0, "fail": 1, "refused": 2}[report["status"]]


if __name__ == "__main__":
    raise SystemExit(main())

